/*
 * Local versions of bgp_node_afi/safi for mgmtd linking.
 * These are duplicated from bgp_vty.c because bgp_cli.c is linked
 * into mgmtd's libmgmt_be_nb.so which doesn't include bgp_vty.c.
 */
static afi_t bgp_cli_node_afi(struct vty *vty)
{
	switch (vty->node) {
	case BGP_IPV6_NODE:
	case BGP_IPV6M_NODE:
	case BGP_IPV6L_NODE:
	case BGP_VPNV6_NODE:
	case BGP_FLOWSPECV6_NODE:
		return AFI_IP6;
	case BGP_EVPN_NODE:
		return AFI_L2VPN;
	default:
		return AFI_IP;
	}
}

static safi_t bgp_cli_node_safi(struct vty *vty)
{
	switch (vty->node) {
	case BGP_VPNV4_NODE:
	case BGP_VPNV6_NODE:
		return SAFI_MPLS_VPN;
	case BGP_IPV4M_NODE:
	case BGP_IPV6M_NODE:
		return SAFI_MULTICAST;
	case BGP_EVPN_NODE:
		return SAFI_EVPN;
	case BGP_IPV4L_NODE:
	case BGP_IPV6L_NODE:
		return SAFI_LABELED_UNICAST;
	case BGP_FLOWSPECV4_NODE:
	case BGP_FLOWSPECV6_NODE:
		return SAFI_FLOWSPEC;
	default:
		return SAFI_UNICAST;
	}
}

