	snprintf(vni_xpath, sizeof(vni_xpath),
		 "./l2vpn-evpn/vni[vni-number='%u']", (uint32_t)vni);
	nb_cli_enqueue_change(vty, vni_xpath, NB_OP_DESTROY, NULL);
