void bgp_peer_group_remote_as_cli_show(struct vty *vty,
				       const struct lyd_node *dnode,
				       bool show_defaults)
{
	const char *peer_group_name;
	const char *remote_as_type = NULL;

	/* Navigate up to get peer-group-name */
	peer_group_name = yang_dnode_get_string(dnode, "../peer-group-name");

	if (yang_dnode_exists(dnode, "remote-as-type"))
		remote_as_type = yang_dnode_get_string(dnode, "remote-as-type");

	/*
	 * If remote-as-type is internal/external, output that form.
	 * Otherwise (explicit AS or no type), output the numeric AS.
	 */
	if (remote_as_type && strcmp(remote_as_type, "internal") == 0) {
		vty_out(vty, " neighbor %s remote-as internal\n",
			peer_group_name);
	} else if (remote_as_type && strcmp(remote_as_type, "external") == 0) {
		vty_out(vty, " neighbor %s remote-as external\n",
			peer_group_name);
	} else if (yang_dnode_exists(dnode, "remote-as")) {
		uint32_t remote_as = yang_dnode_get_uint32(dnode, "remote-as");
		vty_out(vty, " neighbor %s remote-as %u\n",
			peer_group_name, remote_as);
	}
}

