/*
 * Helper to convert afi-safi-name identity to CLI address-family string
 */
static const char *afi_safi_to_cli(const char *afi_safi_name)
{
	/*
	 * Map YANG identity to CLI address-family string.
	 * IMPORTANT: Check more specific patterns first (e.g., l3vpn-ipv4-unicast
	 * before ipv4-unicast) to avoid substring matches.
	 */
	if (strstr(afi_safi_name, "l3vpn-ipv4-unicast"))
		return "ipv4 vpn";
	if (strstr(afi_safi_name, "l3vpn-ipv6-unicast"))
		return "ipv6 vpn";
	if (strstr(afi_safi_name, "ipv4-labeled-unicast"))
		return "ipv4 labeled-unicast";
	if (strstr(afi_safi_name, "ipv6-labeled-unicast"))
		return "ipv6 labeled-unicast";
	if (strstr(afi_safi_name, "l2vpn-evpn"))
		return "l2vpn evpn";
	if (strstr(afi_safi_name, "ipv4-flowspec"))
		return "ipv4 flowspec";
	if (strstr(afi_safi_name, "ipv6-flowspec"))
		return "ipv6 flowspec";
	if (strstr(afi_safi_name, "ipv4-multicast"))
		return "ipv4 multicast";
	if (strstr(afi_safi_name, "ipv6-multicast"))
		return "ipv6 multicast";
	if (strstr(afi_safi_name, "ipv4-unicast"))
		return "ipv4 unicast";
	if (strstr(afi_safi_name, "ipv6-unicast"))
		return "ipv6 unicast";
	return afi_safi_name;
}

/*
 * Neighbor AFI-SAFI cli_show callbacks
 */
void bgp_neighbor_afi_safi_cli_show(struct vty *vty,
				    const struct lyd_node *dnode,
				    bool show_defaults)
{
	const char *afi_safi_name;

	afi_safi_name = yang_dnode_get_string(dnode, "afi-safi-name");
	vty_out(vty, " !\n");
	vty_out(vty, " address-family %s\n", afi_safi_to_cli(afi_safi_name));
}

void bgp_neighbor_afi_safi_cli_show_end(struct vty *vty,
					const struct lyd_node *dnode)
{
	vty_out(vty, " exit-address-family\n");
}

