/*
 * cli_show callback for neighbor AFI/SAFI enabled (neighbor X activate)
 * Uses deferred output to ensure proper address-family block ordering.
 */
void bgp_neighbor_afi_safi_enabled_cli_show(struct vty *vty,
					    const struct lyd_node *dnode,
					    bool show_defaults)
{
	const char *name;
	const char *afi_safi_name;
	afi_t afi;
	safi_t safi;
	bool enabled;

	/*
	 * Navigate up to get neighbor remote-address, interface, or
	 * peer-group-name.  Path: .../(neighbor|unnumbered-neighbor|peer-group)/afi-safis/afi-safi/enabled
	 */
	if (yang_dnode_exists(dnode, "../../../remote-address"))
		name = yang_dnode_get_string(dnode, "../../../remote-address");
	else if (yang_dnode_exists(dnode, "../../../interface"))
		name = yang_dnode_get_string(dnode, "../../../interface");
	else if (yang_dnode_exists(dnode, "../../../peer-group-name"))
		name = yang_dnode_get_string(dnode, "../../../peer-group-name");
	else
		return; /* Unknown parent type */

	/* Get AFI/SAFI from the afi-safi-name key */
	afi_safi_name = yang_dnode_get_string(dnode, "../afi-safi-name");
	if (!bgp_yang_afi_safi_lookup(afi_safi_name, &afi, &safi))
		return; /* Unknown AFI/SAFI */

	enabled = yang_dnode_get_bool(dnode, NULL);

	/* Only output if enabled */
	if (enabled)
		bgp_deferred_write(afi, safi, "  neighbor %s activate\n", name);
}

