/*
 * cli_show callback for neighbor AFI/SAFI allowas-in
 * Uses deferred output to ensure proper address-family block ordering.
 *
 * Path from allow-own-as: .../afi-safi/<afi-type>/as-path-options/allow-own-as
 * - 3 levels up to afi-safi for afi-safi-name
 * - 5 levels up to neighbor for remote-address/peer-group-name/interface
 */
void bgp_neighbor_afi_safi_allowas_in_cli_show(struct vty *vty,
					       const struct lyd_node *dnode,
					       bool show_defaults)
{
	const char *name;
	const char *afi_safi_name;
	afi_t afi;
	safi_t safi;
	uint8_t value;

	/* Get neighbor name (remote-address, interface, or peer-group-name) */
	if (yang_dnode_exists(dnode, "../../../../../remote-address"))
		name = yang_dnode_get_string(dnode, "../../../../../remote-address");
	else if (yang_dnode_exists(dnode, "../../../../../interface"))
		name = yang_dnode_get_string(dnode, "../../../../../interface");
	else if (yang_dnode_exists(dnode, "../../../../../peer-group-name"))
		name = yang_dnode_get_string(dnode, "../../../../../peer-group-name");
	else
		return; /* Unknown parent type */

	/* Get AFI/SAFI from afi-safi-name key (3 levels up) */
	afi_safi_name = yang_dnode_get_string(dnode, "../../../afi-safi-name");
	if (!bgp_yang_afi_safi_lookup(afi_safi_name, &afi, &safi))
		return; /* Unknown AFI/SAFI */

	value = yang_dnode_get_uint8(dnode, NULL);
	bgp_deferred_write(afi, safi, "  neighbor %s allowas-in %u\n", name, value);
}

