void bgp_neighbor_afi_safi_send_community_cli_show(struct vty *vty,
						   const struct lyd_node *dnode,
						   bool show_defaults)
{
	const char *name;
	const char *afi_safi_name;
	afi_t afi;
	safi_t safi;
	bool std_community, ext_community, large_community;

	/*
	 * Path: .../afi-safi/<afi-type>/send-community/send-community
	 * 5 levels up to neighbor, 3 levels up to afi-safi-name.
	 */
	if (yang_dnode_exists(dnode, "../../../../../remote-address"))
		name = yang_dnode_get_string(dnode, "../../../../../remote-address");
	else
		name = yang_dnode_get_string(dnode, "../../../../../peer-group-name");

	afi_safi_name = yang_dnode_get_string(dnode, "../../../afi-safi-name");
	if (!bgp_yang_afi_safi_lookup(afi_safi_name, &afi, &safi))
		return;

	/* Get all three community types */
	std_community = yang_dnode_get_bool(dnode, NULL);
	ext_community = yang_dnode_exists(dnode, "../send-ext-community") ?
			yang_dnode_get_bool(dnode, "../send-ext-community") : false;
	large_community = yang_dnode_exists(dnode, "../send-large-community") ?
			  yang_dnode_get_bool(dnode, "../send-large-community") : false;

	if (!std_community && !ext_community && !large_community) {
		bgp_deferred_write(afi, safi, "  no neighbor %s send-community all\n", name);
	} else if (!std_community) {
		bgp_deferred_write(afi, safi, "  no neighbor %s send-community\n", name);
	} else if (!ext_community) {
		bgp_deferred_write(afi, safi, "  no neighbor %s send-community extended\n", name);
	} else if (!large_community) {
		bgp_deferred_write(afi, safi, "  no neighbor %s send-community large\n", name);
	}
	/* If all are enabled (default), output nothing */
}

