void bgp_neighbor_afi_safi_dampening_cli_show(struct vty *vty,
					      const struct lyd_node *dnode,
					      bool show_defaults)
{
	const char *name;
	const char *afi_safi_name;
	afi_t afi;
	safi_t safi;
	bool enabled;
	uint8_t half_life = 15;
	uint8_t max_suppress = 0;
	uint16_t reuse = 750;
	uint16_t suppress = 2000;
	bool has_max;

	/*
	 * Path: .../afi-safi/<afi-type>/dampening/enable
	 * 5 levels up to neighbor, 3 levels up to afi-safi-name.
	 */
	if (yang_dnode_exists(dnode, "../../../../../remote-address"))
		name = yang_dnode_get_string(dnode, "../../../../../remote-address");
	else
		name = yang_dnode_get_string(dnode, "../../../../../peer-group-name");

	afi_safi_name = yang_dnode_get_string(dnode, "../../../afi-safi-name");
	if (!bgp_yang_afi_safi_lookup(afi_safi_name, &afi, &safi))
		return;

	enabled = yang_dnode_get_bool(dnode, NULL);

	if (!enabled)
		return;

	if (yang_dnode_exists(dnode, "../half-life"))
		half_life = yang_dnode_get_uint8(dnode, "../half-life");
	if (yang_dnode_exists(dnode, "../reuse-threshold"))
		reuse = yang_dnode_get_uint16(dnode, "../reuse-threshold");
	if (yang_dnode_exists(dnode, "../suppress-threshold"))
		suppress = yang_dnode_get_uint16(dnode, "../suppress-threshold");
	has_max = yang_dnode_exists(dnode, "../max-suppress-time");
	if (has_max)
		max_suppress = yang_dnode_get_uint8(dnode, "../max-suppress-time");

	if (has_max && max_suppress != (half_life * 4)) {
		bgp_deferred_write(afi, safi, "  neighbor %s dampening %u %u %u %u\n",
				   name, half_life, reuse, suppress, max_suppress);
	} else if (half_life != 15 || reuse != 750 || suppress != 2000) {
		bgp_deferred_write(afi, safi, "  neighbor %s dampening %u %u %u %u\n",
				   name, half_life, reuse, suppress, half_life * 4);
	} else {
		bgp_deferred_write(afi, safi, "  neighbor %s dampening\n", name);
	}
}

