void bgp_neighbor_timers_cli_show(struct vty *vty,
				  const struct lyd_node *dnode,
				  bool show_defaults)
{
	const char *name;
	uint16_t keepalive, holdtime;

	/* Check if this is a neighbor or peer-group */
	if (yang_dnode_exists(dnode, "../../remote-address"))
		name = yang_dnode_get_string(dnode, "../../remote-address");
	else
		name = yang_dnode_get_string(dnode, "../../peer-group-name");

	holdtime = yang_dnode_get_uint16(dnode, NULL);
	if (yang_dnode_exists(dnode, "../keepalive"))
		keepalive = yang_dnode_get_uint16(dnode, "../keepalive");
	else
		keepalive = holdtime / 3;

	/* Don't output when values are 0 (unset) */
	if (holdtime == 0 || keepalive == 0)
		return;

	vty_out(vty, " neighbor %s timers %u %u\n", name, keepalive, holdtime);
}

