/*
 * Default AFI-SAFI cli_show callback
 * This outputs "no bgp default ipv4-unicast" when ipv4-unicast is NOT in the list
 */
void bgp_global_default_afi_safi_cli_show(struct vty *vty,
					  const struct lyd_node *dnode,
					  bool show_defaults)
{
	const char *afi_safi_name;

	afi_safi_name = yang_dnode_get_string(dnode, NULL);

	/*
	 * The default-afi-safi leaf-list contains AFI/SAFIs that ARE activated
	 * by default. If ipv4-unicast is in the list, don't output anything
	 * (it's the default). Only output "no bgp default ipv4-unicast" when
	 * ipv4-unicast is NOT in the list - but since this callback is called
	 * for each entry IN the list, we can't detect absence here.
	 *
	 * Actually, the CLI "no bgp default ipv4-unicast" REMOVES ipv4-unicast
	 * from the default list, which means we need to check if ipv4-unicast
	 * is NOT present. But this callback only fires when entries exist.
	 *
	 * We need a different approach - check at the BGP router level if
	 * ipv4-unicast is absent from default-afi-safi list.
	 */
	(void)afi_safi_name; /* Not used - see comment above */
}

/*
 * Redistribution list cli_show callback
 */
void bgp_redistribution_list_cli_show(struct vty *vty,
				      const struct lyd_node *dnode,
				      bool show_defaults)
{
	const char *route_type;
	uint16_t instance = 0;

	route_type = yang_dnode_get_string(dnode, "route-type");

	if (yang_dnode_exists(dnode, "route-instance"))
		instance = yang_dnode_get_uint16(dnode, "route-instance");

	vty_out(vty, "  redistribute %s", route_type);
	if (instance)
		vty_out(vty, " %u", instance);

	if (yang_dnode_exists(dnode, "metric")) {
		uint32_t metric = yang_dnode_get_uint32(dnode, "metric");
		vty_out(vty, " metric %u", metric);
	}

	if (yang_dnode_exists(dnode, "rmap-policy-import")) {
		const char *rmap = yang_dnode_get_string(dnode, "rmap-policy-import");
		vty_out(vty, " route-map %s", rmap);
	}

	vty_out(vty, "\n");
}

