void routing_control_plane_protocols_control_plane_protocol_bgp_cli_show(struct vty *vty, const struct lyd_node *dnode, bool show_defaults)
{
	const char *vrf_name;
	as_t as;

	vrf_name = yang_dnode_get_string(dnode, "../vrf");
	as = yang_dnode_get_uint32(dnode, "global/local-as");

	vty_out(vty, "!\n");
	vty_out(vty, "router bgp %u", as);
	if (strcmp(vrf_name, VRF_DEFAULT_NAME) != 0)
		vty_out(vty, " vrf %s", vrf_name);

	/* Output as-notation if configured */
	if (yang_dnode_exists(dnode, "global/as-notation")) {
		int notation = yang_dnode_get_enum(dnode, "global/as-notation");
		switch (notation) {
		case 0: /* plain */
			vty_out(vty, " as-notation plain");
			break;
		case 1: /* dot */
			vty_out(vty, " as-notation dot");
			break;
		case 2: /* dot+ */
			vty_out(vty, " as-notation dot+");
			break;
		}
	}
	vty_out(vty, "\n");
}

