void routing_control_plane_protocols_control_plane_protocol_bgp_global_afi_safis_afi_safi_cli_write(struct vty *vty, const struct lyd_node *dnode, bool show_defaults)
{
	const char *afi_safi_name;
	afi_t afi;
	safi_t safi;

	afi_safi_name = yang_dnode_get_string(dnode, "afi-safi-name");
	yang_afi_safi_identity2value(afi_safi_name, &afi, &safi);

	/* Output the address-family line */
	vty_out(vty, " !\n");
	vty_out(vty, " address-family ");
	if (afi == AFI_IP) {
		if (safi == SAFI_UNICAST)
			vty_out(vty, "ipv4 unicast");
		else if (safi == SAFI_MULTICAST)
			vty_out(vty, "ipv4 multicast");
		else if (safi == SAFI_LABELED_UNICAST)
			vty_out(vty, "ipv4 labeled-unicast");
		else if (safi == SAFI_MPLS_VPN)
			vty_out(vty, "ipv4 vpn");
		else if (safi == SAFI_FLOWSPEC)
			vty_out(vty, "ipv4 flowspec");
		else
			vty_out(vty, "ipv4 unknown-safi-%d", safi);
	} else if (afi == AFI_IP6) {
		if (safi == SAFI_UNICAST)
			vty_out(vty, "ipv6 unicast");
		else if (safi == SAFI_MULTICAST)
			vty_out(vty, "ipv6 multicast");
		else if (safi == SAFI_LABELED_UNICAST)
			vty_out(vty, "ipv6 labeled-unicast");
		else if (safi == SAFI_MPLS_VPN)
			vty_out(vty, "ipv6 vpn");
		else if (safi == SAFI_FLOWSPEC)
			vty_out(vty, "ipv6 flowspec");
		else
			vty_out(vty, "ipv6 unknown-safi-%d", safi);
	} else if (afi == AFI_L2VPN) {
		if (safi == SAFI_EVPN)
			vty_out(vty, "l2vpn evpn");
		else
			vty_out(vty, "l2vpn unknown-safi-%d", safi);
	} else {
		vty_out(vty, "unknown-afi-%d unknown-safi-%d", afi, safi);
	}
	vty_out(vty, "\n");
}

