void routing_control_plane_protocols_control_plane_protocol_bgp_global_afi_safis_afi_safi_ipv6_unicast_redistribution_list_cli_write(struct vty *vty, const struct lyd_node *dnode, bool show_defaults)
{
	const char *route_type;
	uint16_t route_instance;
	const char *rmap = NULL;

	route_type = yang_dnode_get_string(dnode, "route-type");
	route_instance = yang_dnode_get_uint16(dnode, "route-instance");

	/* Get optional route-map */
	if (yang_dnode_exists(dnode, "rmap-policy-import"))
		rmap = yang_dnode_get_string(dnode, "rmap-policy-import");

	/* Output based on protocol type */
	if (route_instance > 0) {
		/* Table with instance */
		if (yang_dnode_exists(dnode, "metric")) {
			uint32_t metric = yang_dnode_get_uint32(dnode, "metric");
			if (rmap)
				vty_out(vty, " redistribute %s %u metric %u route-map %s\n",
					route_type, route_instance, metric, rmap);
			else
				vty_out(vty, " redistribute %s %u metric %u\n",
					route_type, route_instance, metric);
		} else {
			if (rmap)
				vty_out(vty, " redistribute %s %u route-map %s\n",
					route_type, route_instance, rmap);
			else
				vty_out(vty, " redistribute %s %u\n",
					route_type, route_instance);
		}
	} else {
		/* Standard redistribution without instance */
		if (yang_dnode_exists(dnode, "metric")) {
			uint32_t metric = yang_dnode_get_uint32(dnode, "metric");
			if (rmap)
				vty_out(vty, " redistribute %s metric %u route-map %s\n",
					route_type, metric, rmap);
			else
				vty_out(vty, " redistribute %s metric %u\n",
					route_type, metric);
		} else {
			if (rmap)
				vty_out(vty, " redistribute %s route-map %s\n",
					route_type, rmap);
			else
				vty_out(vty, " redistribute %s\n", route_type);
		}
	}
}

