void routing_control_plane_protocols_control_plane_protocol_bgp_global_default_afi_safi_cli_write(struct vty *vty, const struct lyd_node *dnode, bool show_defaults)
{
	const char *afi_safi_name = yang_dnode_get_string(dnode, NULL);
	afi_t afi;
	safi_t safi;

	yang_afi_safi_identity2value(afi_safi_name, &afi, &safi);

	/* ipv4-unicast is the default, so "bgp default ipv4-unicast" should only be shown if ipv4-unicast is present (enabled)
	 * and "no bgp default ipv4-unicast" style output is handled differently.
	 * For leaf-list, each entry means it's enabled, so we output the positive form.
	 */
	if (afi == AFI_IP && safi == SAFI_UNICAST) {
		/* For ipv4-unicast, presence means it's explicitly enabled (unusual since it's default) */
		vty_out(vty, "  bgp default ipv4-unicast\n");
	} else if (afi == AFI_IP && safi == SAFI_MULTICAST) {
		vty_out(vty, "  bgp default ipv4-multicast\n");
	} else if (afi == AFI_IP && safi == SAFI_MPLS_VPN) {
		vty_out(vty, "  bgp default ipv4-vpn\n");
	} else if (afi == AFI_IP && safi == SAFI_LABELED_UNICAST) {
		vty_out(vty, "  bgp default ipv4-labeled-unicast\n");
	} else if (afi == AFI_IP && safi == SAFI_FLOWSPEC) {
		vty_out(vty, "  bgp default ipv4-flowspec\n");
	} else if (afi == AFI_IP6 && safi == SAFI_UNICAST) {
		vty_out(vty, "  bgp default ipv6-unicast\n");
	} else if (afi == AFI_IP6 && safi == SAFI_MULTICAST) {
		vty_out(vty, "  bgp default ipv6-multicast\n");
	} else if (afi == AFI_IP6 && safi == SAFI_MPLS_VPN) {
		vty_out(vty, "  bgp default ipv6-vpn\n");
	} else if (afi == AFI_IP6 && safi == SAFI_LABELED_UNICAST) {
		vty_out(vty, "  bgp default ipv6-labeled-unicast\n");
	} else if (afi == AFI_IP6 && safi == SAFI_FLOWSPEC) {
		vty_out(vty, "  bgp default ipv6-flowspec\n");
	} else if (afi == AFI_L2VPN && safi == SAFI_EVPN) {
		vty_out(vty, "  bgp default l2vpn-evpn\n");
	}
}

